package com.example.starter.race.domain;

import java.util.List;

/**
 * 分段提交不变量的纯逻辑校验，不涉及数据库与事务。
 *
 * <p>规则（违反任一则提交被拒绝，不写入）：
 * <ul>
 *   <li>elapsedMillis 取值 1~86400000；</li>
 *   <li>elapsedMillis 必须严格小于该选手已有原始完赛耗时（无完赛耗时也拒绝）；</li>
 *   <li>同一选手同一检查点最多一条；</li>
 *   <li>允许乱序到达，但按检查点顺序查看时耗时必须严格递增：
 *       新记录必须严格大于已存在的最近前序检查点耗时，
 *       并严格小于已存在的最近后序检查点耗时。</li>
 * </ul>
 */
public final class CheckpointRules {

    /** 分段耗时上界（毫秒），含端点：1天。 */
    public static final long MAX_ELAPSED_MILLIS = 86_400_000L;

    private CheckpointRules() {
    }

    /**
     * 校验一次分段提交。
     *
     * @param existingForRunner 该选手已存在的全部分段记录（任意顺序）
     * @param targetPosition    本次提交检查点的顺序
     * @param elapsedMillis     本次提交的累计耗时
     * @param finishTimeMs      该选手已有原始完赛耗时；null 表示尚无完赛计时
     * @return 违反不变量时的错误信息；合法时为 null
     */
    public static String validate(
            List<? extends TimingView> existingForRunner,
            int targetPosition,
            long elapsedMillis,
            Long finishTimeMs) {
        if (elapsedMillis < 1L || elapsedMillis > MAX_ELAPSED_MILLIS) {
            return "分段耗时毫秒数必须在 1~86400000 之间";
        }
        if (finishTimeMs == null) {
            return "选手尚无原始完赛耗时，不能提交分段记录";
        }
        if (elapsedMillis >= finishTimeMs) {
            return "分段耗时必须严格小于该选手原始完赛耗时";
        }

        TimingView predecessor = null;
        TimingView successor = null;
        for (TimingView timing : existingForRunner) {
            if (timing.position() == targetPosition) {
                return "同一选手同一检查点最多一条分段记录";
            }
            if (timing.position() < targetPosition) {
                if (predecessor == null || timing.position() > predecessor.position()) {
                    predecessor = timing;
                }
            } else {
                if (successor == null || timing.position() < successor.position()) {
                    successor = timing;
                }
            }
        }

        if (predecessor != null && elapsedMillis <= predecessor.elapsedMillis()) {
            return "分段耗时必须严格大于前一检查点耗时: position=" + predecessor.position();
        }
        if (successor != null && elapsedMillis >= successor.elapsedMillis()) {
            return "分段耗时必须严格小于后一检查点耗时: position=" + successor.position();
        }
        return null;
    }
}

package com.example.starter.race.domain;

import java.util.List;

/**
 * 单个选手的成绩条目。
 *
 * @param bib                     参赛号
 * @param rank                    名次，从1开始；并列同名次且跳号（1、1、3）；非 RANKED 为 null
 * @param status                  成绩状态
 * @param finishTimeMs            原始完赛耗时（毫秒）；计时缺失为 null
 * @param penaltyMs               全部未撤销加时处罚的合计毫秒数；无加时为 0
 * @param totalTimeMs             总耗时=原始完赛耗时+生效加时（毫秒）；未排名时为 null
 * @param checkpointCount         赛事配置的检查点总数；未配置检查点的赛事为 0
 * @param coveredCheckpointCount  该选手已有分段记录的检查点数量
 * @param missingCheckpoints      该选手尚未通过的检查点代码，按检查点顺序排列；全部覆盖或无检查点时为空列表
 */
public record ResultEntry(
        String bib,
        Integer rank,
        EntryStatus status,
        Long finishTimeMs,
        long penaltyMs,
        Long totalTimeMs,
        int checkpointCount,
        int coveredCheckpointCount,
        List<String> missingCheckpoints
) {

    /** 未配置检查点赛事使用的兼容构造器：检查点计数均为 0、缺失列表为空。 */
    public ResultEntry(
            String bib,
            Integer rank,
            EntryStatus status,
            Long finishTimeMs,
            long penaltyMs,
            Long totalTimeMs) {
        this(bib, rank, status, finishTimeMs, penaltyMs, totalTimeMs, 0, 0, List.of());
    }
}

