private static void validateStageDefinitions(List<StageDefinition> definitions) {
    if (definitions.size() < 2 || definitions.size() > 5) throw BadRequest("阶段数量必须在 2~5 之间");
    for (int i = 0; i < definitions.size(); i++) {
        StageDefinition def = definitions.get(i);
        if (def.stageNo() != i + 1) throw BadRequest("阶段序号必须从1连续递增，缺少 stageNo=" + (i+1));
        // checkpoints validation like single-day
        List<CheckpointDefinition> cps = def.checkpoints();
        if (cps.isEmpty() || cps.size() > 20) throw BadRequest("每阶段检查点数量必须在 1~20 之间");
        Set<String> codes; Set<Integer> positions;
        for (cp : cps) { if (!codes.add(cp.checkpointCode())) throw BadRequest("检查点代码在阶段内重复: " + code); positions.add(cp.position()); }
        for (int expected = 1; expected <= cps.size(); expected++) if (!positions.contains(expected)) throw BadRequest("阶段内检查点顺序必须从1连续递增，缺少 position=" + expected);
    }
}
