                    bumpVersion(race, request.expectedVersion());
                    StageTimingRow row = new StageTimingRow(
                            request.timingId(), raceId, stageNo, bib, request.checkpointCode(),
                            checkpoint.position(), request.elapsedMillis(), clock.millis());
